import{_ as n,o as i,c as a,a0 as t}from"./chunks/framework.BMIT1c_r.js";const u=JSON.parse('{"title":"1. Solvable Idealized Settings: Paper List","description":"","frontmatter":{},"headers":[],"relativePath":"solvable-settings.md","filePath":"solvable-settings.md"}'),r={name:"solvable-settings.md"};function l(o,e,s,m,g,d){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="_1-solvable-idealized-settings-paper-list" tabindex="-1">1. Solvable Idealized Settings: Paper List <a class="header-anchor" href="#_1-solvable-idealized-settings-paper-list" aria-label="Permalink to &quot;1. Solvable Idealized Settings: Paper List&quot;">​</a></h1><blockquote><p>A reliable way to build scientific understanding in complex systems is to study pared-down yet representative settings where quantitative calculations are possible, mirroring physics&#39; use of the harmonic oscillator or the hydrogen atom.</p></blockquote><h2 id="a-linearization-in-the-data-deep-linear-networks" tabindex="-1">A. Linearization in the Data (Deep Linear Networks) <a class="header-anchor" href="#a-linearization-in-the-data-deep-linear-networks" aria-label="Permalink to &quot;A. Linearization in the Data (Deep Linear Networks)&quot;">​</a></h2><p><em>Focuses on architectures that remove all nonlinear activation functions but remain highly nonlinear in their parameters, isolating the unique effects of network depth and layer interactions.</em></p><ul><li><strong>Saxe et al. [2014]</strong> — <em>Exact solutions to the nonlinear dynamics of learning in deep linear neural networks</em></li><li><strong>Nam et al. [2025]</strong> — <em>Position: Solve layerwise linear models first to understand neural dynamical phenomena (neural collapse, emergence, lazy/rich regime, and grokking)</em></li><li><strong>Baldi &amp; Hornik [1989]</strong> — <em>Neural networks and principal component analysis: Learning from examples without local minima</em></li><li><strong>Gissin et al. [2019]</strong> — <em>The implicit bias of depth: How incremental learning drives generalization</em></li><li><strong>Atanasov et al. [2021]</strong> — <em>Neural networks as kernel learners: The silent alignment effect</em></li><li><strong>Even et al. [2023]</strong> — <em>(s) gd over diagonal linear networks: Implicit bias, large stepsizes and edge of stability</em></li><li><strong>Woodworth et al. [2020]</strong> — <em>Kernel and rich regimes in overparametrized models</em></li><li><strong>Kunin et al. [2024]</strong> — <em>Get rich quick: exact solutions reveal how unbalanced initializations promote rapid feature learning</em></li><li><strong>Fukumizu [1998]</strong> — <em>Effect of batch learning in multilayer neural networks</em></li><li><strong>Tarmoun et al. [2021]</strong> — <em>Understanding the dynamics of gradient flow in overparameterized linear models</em></li><li><strong>Dominé et al. [2025]</strong> — <em>From lazy to rich: Exact learning dynamics in deep linear networks</em></li><li><strong>Lampinen &amp; Ganguli [2018]</strong> — <em>An analytic theory of generalization dynamics and transfer learning in deep linear networks</em></li><li><strong>Kalimeris et al. [2019]</strong> — <em>Sgd on neural networks learns functions of increasing complexity</em></li><li><strong>Simon et al. [2023b]</strong> — <em>On the stepwise nature of self-supervised learning</em></li><li><strong>Gidel et al. [2019]</strong> — <em>Implicit regularization of discrete gradient dynamics in linear neural networks</em></li><li><strong>Li et al. [2021a]</strong> — <em>Towards resolving the implicit bias of gradient descent for matrix factorization: Greedy low-rank learning</em></li><li><strong>Jacot et al. [2021]</strong> — <em>Saddle-to-saddle dynamics in deep linear networks: Small initialization training, symmetry, and sparsity</em></li><li><strong>Pesme &amp; Flammarion [2023]</strong> — <em>Saddle-to-saddle dynamics in diagonal linear networks</em></li><li><strong>Arora et al. [2018]</strong> — <em>On the optimization of deep networks: Implicit acceleration by overparameterization</em></li><li><strong>Arora et al. [2019b]</strong> — <em>Implicit regularization in deep matrix factorization</em></li><li><strong>Pesme et al. [2021]</strong> — <em>Implicit bias of sgd for diagonal linear networks: a provable benefit of stochasticity</em></li><li><strong>Chen et al. [2024]</strong> — <em>Stochastic collapse: How gradient noise attracts sgd dynamics towards simpler subnetworks</em></li><li><strong>Ziyin et al. [2022]</strong> — <em>Exact solutions of a deep linear network</em></li><li><strong>Wang &amp; Jacot [2024]</strong> — <em>Implicit bias of sgd in l-2-regularized linear dnns: One-way jumps from high to low rank</em></li></ul><hr><h2 id="b-linearization-in-the-parameters-kernel-methods-ntk" tabindex="-1">B. Linearization in the Parameters (Kernel Methods &amp; NTK) <a class="header-anchor" href="#b-linearization-in-the-parameters-kernel-methods-ntk" aria-label="Permalink to &quot;B. Linearization in the Parameters (Kernel Methods &amp; NTK)&quot;">​</a></h2><p><em>Focuses on settings where networks are well-approximated by their first-order Taylor expansion around initial parameters, transforming least-squares training into tractable kernel ridge regression.</em></p><ul><li><strong>Jacot et al. [2018]</strong> — <em>Neural tangent kernel: Convergence and generalization in neural networks</em></li><li><strong>Lee et al. [2019]</strong> — <em>Wide neural networks of any depth evolve as linear models under gradient descent</em></li><li><strong>Chizat et al. [2019]</strong> — <em>On lazy training in differentiable programming</em></li><li><strong>Liu et al. [2020]</strong> — <em>On the linearity of large non-linear models: when and why the tangent kernel is constant</em></li><li><strong>Malladi et al. [2023]</strong> — <em>A kernel-based view of language model fine-tuning</em></li><li><strong>Ren &amp; Sutherland [2025]</strong> — <em>Learning dynamics of LLM finetuning</em></li><li><strong>Arora et al. [2019c]</strong> — <em>On exact computation with an infinitely wide neural net</em></li><li><strong>Geifman et al. [2020]</strong> — <em>On the similarity between the laplace and neural tangent kernels</em></li><li><strong>Jacot et al. [2020]</strong> — <em>Kernel alignment risk estimator: Risk prediction from training data</em></li><li><strong>Canatar et al. [2021]</strong> — <em>Spectral bias and task-model alignment explain generalization in kernel regression and infinitely wide neural networks</em></li><li><strong>Loureiro et al. [2021]</strong> — <em>Learning curves of generic features maps for realistic datasets with a teacher-student model</em></li><li><strong>Hastie et al. [2022]</strong> — <em>Surprises in high-dimensional ridgeless least squares interpolation</em></li><li><strong>Wei et al. [2022]</strong> — <em>More than a toy: Random matrix models predict how real-world neural representations generalize</em></li><li><strong>Simon et al. [2023a]</strong> — <em>The eigenlearning framework: A conservation law perspective on kernel ridge regression and wide neural networks</em></li><li><strong>Basri et al. [2020]</strong> — <em>Frequency bias in neural networks for input of non-uniform density</em></li><li><strong>Karkada et al. [2025]</strong> — <em>Predicting kernel regression learning curves from only raw data statistics</em></li><li><strong>Belkin et al. [2019]</strong> — <em>Reconciling modern machine-learning practice and the classical bias-variance trade-off</em></li><li><strong>Advani et al. [2020]</strong> — <em>High-dimensional dynamics of generalization error in neural networks</em></li><li><strong>Caponnetto &amp; de Vito [2007]</strong> — <em>Optimal rates for the regularized least-squares algorithm</em></li><li><strong>Pillaud-Vivien et al. [2018]</strong> — <em>Statistical optimality of stochastic gradient descent on hard learning problems through multiple passes</em></li><li><strong>Cui et al. [2023]</strong> — <em>Error scaling laws for kernel classification under source and capacity conditions</em></li><li><strong>Atanasov et al. [2024]</strong> — <em>Scaling and renormalization in high-dimensional regression</em></li><li><strong>Ghorbani et al. [2020]</strong> — <em>When do neural networks outperform kernel methods?</em></li><li><strong>Vyas et al. [2022]</strong> — <em>Limitations of the ntk for understanding generalization in deep learning</em></li></ul><hr><h2 id="c-beyond-linearization-genuinely-nonlinear-toy-models" tabindex="-1">C. Beyond Linearization (Genuinely Nonlinear Toy Models) <a class="header-anchor" href="#c-beyond-linearization-genuinely-nonlinear-toy-models" aria-label="Permalink to &quot;C. Beyond Linearization (Genuinely Nonlinear Toy Models)&quot;">​</a></h2><p><em>Focuses on solvable minimal models that remain genuinely nonlinear in both the data and the parameters, capturing explicit feature-learning mechanisms.</em></p><ul><li><strong>Abbe et al. [2022]</strong> — <em>The merged-staircase property: a necessary and nearly sufficient condition for sgd learning of sparse functions on two-layer neural networks</em></li><li><strong>Damian et al. [2022b]</strong> — <em>Neural networks can learn representations with gradient descent</em></li><li><strong>Bietti et al. [2022]</strong> — <em>Learning single-index models with shallow neural networks</em></li><li><strong>Ba et al. [2022]</strong> — <em>High-dimensional asymptotics of feature learning: How one gradient step improves the representation</em></li><li><strong>Dandi et al. [2023]</strong> — <em>How two-layer neural networks learn, one (giant) step at a time</em></li><li><strong>Barbier et al. [2019]</strong> — <em>Optimal errors and phase transitions in high-dimensional generalized linear models</em></li><li><strong>Aubin et al. [2018]</strong> — <em>The committee machine: Computational to statistical gaps in learning a two-layers neural network</em></li><li><strong>Mignacco et al. [2020]</strong> — <em>Dynamical mean-field theory for stochastic gradient descent in gaussian mixture classification</em></li><li><strong>Erba et al. [2025]</strong> — <em>The nuclear route: Sharp asymptotics of erm in overparameterized quadratic networks</em></li><li><strong>Ben Arous et al. [2025]</strong> — <em>Learning quadratic neural networks in high dimensions: Sgd dynamics and scaling laws</em></li><li><strong>Defilippis et al. [2025]</strong> — <em>Scaling laws and spectra of shallow neural networks in the feature learning regime</em></li><li><strong>Ren et al. [2025]</strong> — <em>Emergence and scaling laws in sgd learning of shallow neural networks</em></li><li><strong>Soudry et al. [2018a]</strong> — <em>The implicit bias of gradient descent on separable data</em></li><li><strong>Lyu and Li [2020]</strong> — <em>Gradient descent maximizes the margin of homogeneous neural networks</em></li><li><strong>Saad &amp; Solla [1995]</strong> — <em>Exact solution for on-line learning in multilayer neural networks</em></li><li><strong>Goldt et al. [2019]</strong> — <em>Dynamics of stochastic gradient descent for two-layer neural networks in the teacher-student setup</em></li><li><strong>Ben Arous et al. [2022]</strong> — <em>High-dimensional limit theorems for sgd: Effective dynamics and critical scaling</em></li><li><strong>Veiga et al. [2022]</strong> — <em>Phase diagram of stochastic gradient descent in high-dimensional two-layer neural networks</em></li><li><strong>Zavatone-Veth et al. [2025]</strong> — <em>Summary statistics of learning link changing neural representations to behavior</em></li><li><strong>Nichani et nala. [2025]</strong> — <em>Understanding factual recall in transformers via associative memories</em></li><li><strong>Morwani et al. [2023]</strong> — <em>Feature emergence via margin maximization: case studies in algebraic tasks</em></li><li><strong>Gromov [2023]</strong> — <em>Grokking modular arithmetic</em></li><li><strong>Kunin et al. [2025]</strong> — <em>Alternating gradient flows: A theory of feature learning in two-layer neural networks</em></li><li><strong>Zhang et al. [2025]</strong> — <em>Training dynamics of in-context learning in linear attention</em></li><li><strong>Boncoraglio et al. [2025]</strong> — <em>Single-head attention in high dimensions: A theory of generalization, weights spectra, and scaling laws</em></li><li><strong>Bordelon et al. [2025]</strong> — <em>How feature learning can improve neural scaling laws</em></li></ul>',13)])])}const h=n(r,[["render",l]]);export{u as __pageData,h as default};
